def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 687.0816966804601  # OPT_PARAM: {"initial": 687.0816966804601, "min": 600, "max": 850, "type": "float"}
    order_cap = 96.70029945055367  # OPT_PARAM: {"initial": 96.70029945055367, "min": 90, "max": 140, "type": "float"}
    safety_stock = 95.0  # OPT_PARAM: {"initial": 95.0, "min": 70, "max": 130, "type": "float"}
    demand_forecast = 88.72851442658198  # OPT_PARAM: {"initial": 88.72851442658198, "min": 85, "max": 115, "type": "float"}

    # Calculate inventory position
    inventory_position = on_hand_inventory + sum(pipeline_orders)

    # Calculate desired order amount based on base stock policy
    desired_order = base_stock - inventory_position

    # Adjust for safety stock to reduce lost sales
    if inventory_position < safety_stock:
        desired_order += safety_stock - inventory_position

    # Smooth ordering by considering demand forecast
    smoothing_factor = 0.3900576490522569  # OPT_PARAM: {"initial": 0.3900576490522569, "min": 0.3, "max": 0.9, "type": "float"}
    smoothed_order = smoothing_factor * desired_order + (1 - smoothing_factor) * demand_forecast

    # Apply order cap and ensure non-negative
    order_amount = max(0, min(smoothed_order, order_cap))

    # Round to nearest integer (orders must be integer quantities)
    return order_amount
